sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_progMode;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_holdMax;
uniform float amzp_burstChance;
uniform float amzp_burstLen;
uniform float amzp_cycleSpeed;
uniform float amzp_slideSpeed;
uniform float amzp_noiseRate;
uniform float2 amzp_blockXY;
uniform float amzp_complexity;
uniform float amzp_persist;
uniform float amzp_density;
uniform float amzp_softness;
uniform float amzp_graySteps;
uniform float amzp_noiseAngle;
uniform float amzp_colorNoise;
uniform float amzp_seed;
uniform float2 amzp_offs;
uniform float amzp_typex;
uniform float amzp_typey;
uniform float amzp_edges;
uniform float amzp_tileCrop;
uniform float amzp_fromCtr;
uniform float amzp_invert;
uniform float amzp_showNoise;
uniform float amzp_overdrawOn;
    float gSlide;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float2 rot2(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float h21(float2 p, float k) {
        float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973) + k * 0.1137);
        q += dot(q, q.yzx + 33.33);
        return fract((q.x + q.y) * q.z);
    }
    float blockNoise(float2 p, float stp, float ch, float M) {
        float W = max(amzp_blockXY.x, 1.0);
        float H = max(amzp_blockXY.y, 1.0);
        float sum = 0.0, amp = 1.0, norm = 0.0, var = 0.0;
        float key = stp * 7.13 + ch * 31.7 + amzp_seed * 1.37;
        for (int i = 0; i < 10; i++) {
            if (float(i) >= amzp_complexity) break;
            float sc = pow(2.0, float(i));
            float2 cs = float2(W, H) / sc;
            if (cs.y < 0.75) break;
            float row = floor(p.y / cs.y);
            float shift = h21(float2(row, float(i)), key + 3.0) * cs.x;
            shift += gSlide * (0.3 + h21(float2(row, float(i)), amzp_seed + 5.0)) * W;
            float2 cell = float2(floor((p.x + shift) / cs.x), row);
            sum += h21(cell + float(i) * 17.0, key) * amp;
            norm += amp;
            var += amp * amp;
            amp *= amzp_persist;
        }
        float z = (sum - 0.5 * norm) / sqrt(max(var, 1e-6) / 12.0);
        float v = clamp(0.5 + 0.2 * z, 0.0, 1.0);
        float th = 1.0 - clamp(amzp_density, 0.0, 1.0);
        float sw = max(amzp_softness, 0.0) * 0.5 + 0.0005;
        float m = smoothstep(th - sw * 0.25, th + sw, v);
        float g = h21(floor(p / float2(W, H) * 4.0) + 5.0, key + 9.0);
        float steps = max(floor(amzp_graySteps + 0.5), 1.0);
        float lvl = steps <= 1.0 ? 1.0 : (floor(g * steps) + 1.0) / steps;
        return clamp(m * mix(1.0, lvl, step(1.5, steps)), 0.0, 1.0);
    }
    float2 edgeFix(float2 l) {
        if (int(amzp_edges) == 0) return clamp(l, 0.0, 1.0);
        if (int(amzp_edges) == 1) return float2(1.0) - abs(mod(l, float2(2.0)) - float2(1.0));
        if (int(amzp_edges) == 3) {
            float c = clamp(amzp_tileCrop, 0.0, 0.45);
            float2 u = (l - c) / (1.0 - 2.0 * c);
            return c + (float2(1.0) - abs(mod(u, float2(2.0)) - float2(1.0))) * (1.0 - 2.0 * c);
        }
        return l;
    }
    float pick(int t, float3 c) {
        if (t == 0) return dot(c, float3(0.2126, 0.7152, 0.0722));
        if (t == 1) return c.r;
        if (t == 2) return c.g;
        return c.b;
    }
    void nmMain() {
        float2 W = layer;
        float M = min(W.x, W.y);
        float T = amzp_progress * 10.0 + ((amzp_autop>0.5) ? time * amzp_autoSpeed : 0.0);
        float k = floor(T * max(amzp_noiseRate, 0.0) + 1e-4);
        float stp = k, amt = 1.0;
        gSlide = 0.0;
        if (int(amzp_progMode) == 1) {
            float hm = max(floor(amzp_holdMax + 0.5), 1.0);
            float grp = floor(k / hm);
            float len = 1.0 + floor(h21(float2(grp, 1.0), amzp_seed + 11.0) * hm);
            stp = grp * 977.0 + floor(mod(k, hm) / len);
        } else if (int(amzp_progMode) == 2) {
            float bl = max(amzp_burstLen, 0.02);
            float sg = floor(T / bl);
            float on = step(h21(float2(sg, 2.0), amzp_seed + 13.0), clamp(amzp_burstChance, 0.0, 1.0));
            float len = mix(0.3, 1.0, h21(float2(sg, 3.0), amzp_seed + 17.0));
            amt = on * step(fract(T / bl), len);
        } else if (int(amzp_progMode) == 3) {
            amt = 0.5 - 0.5 * cos(6.2831853 * T * amzp_cycleSpeed);
        } else if (int(amzp_progMode) == 4) {
            stp = floor(T * max(amzp_noiseRate, 0.0) * 0.1 + 1e-4);
            gSlide = T * amzp_slideSpeed * 0.5;
        } else if (int(amzp_progMode) == 5) {
            float f = fract(T * amzp_cycleSpeed);
            amt = f * f;
        }
        float2 p = rot2((amzLayerNorm() - 0.5) * W, -radians(amzp_noiseAngle)) * float2(1.0, -1.0);
        float n0 = blockNoise(p, stp, 0.0, M);
        float3 nz = (amzp_colorNoise>0.5) ? float3(n0, blockNoise(p, stp, 1.0, M), blockNoise(p, stp, 2.0, M)) : float3(n0);
        float4 orig = amzTexture(0, amzScreenNorm());
        if ((amzp_showNoise>0.5)) { amzOutput = float4(nz * amt, 1.0) * orig.a; return; }
        float px = pick(int(amzp_typex), nz), py = pick(int(amzp_typey), nz);
        if ((amzp_fromCtr>0.5)) { px = (px - 0.5) * 2.0; py = (py - 0.5) * 2.0; }
        if ((amzp_invert>0.5)) { px = 1.0 - px; py = 1.0 - py; }
        float2 l = amzLayerNorm() + float2(-amzp_offs.x * px, amzp_offs.y * py) * amt / max(W, float2(1.0));
        bool lin = l.x >= 0.0 && l.x <= 1.0 && l.y >= 0.0 && l.y <= 1.0;
        bool pin = amzLayerNorm().x >= 0.0 && amzLayerNorm().x <= 1.0 && amzLayerNorm().y >= 0.0 && amzLayerNorm().y <= 1.0;
        if (!lin && (int(amzp_edges) == 2 || !pin)) { amzOutput = float4(0.0); return; }
        amzOutput = amzTexture(0, l2s(pin ? edgeFix(l) : l));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
